import re

_TOKEN_RE = re.compile(r"\s*(?:(\d+)|([A-Z]\d+)|([A-Z]+)|(<>|<=|>=|[+\-*/(),:=<>]))")
_OP_INS = {"+": ("ADD",), "-": ("SUB",), "*": ("MUL",), "/": ("DIV",)}
_CMP_OPS = {"=", "<>", "<", "<=", ">", ">="}


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    memo: dict[str, int | str] = {}
    formulas: dict[str, str] = {}

    for name, content in cells.items():
        s = content.strip()
        if s.startswith("="):
            formulas[name] = s[1:]
        else:
            memo[name] = int(s)

    range_cache: dict[tuple[int, int, int, int], tuple[str, ...]] = {}

    def get_range_cells(c1_name: str, c2_name: str) -> tuple[str, ...]:
        c1, r1 = ord(c1_name[0]), int(c1_name[1:])
        c2, r2 = ord(c2_name[0]), int(c2_name[1:])
        if c1 > c2:
            c1, c2 = c2, c1
        if r1 > r2:
            r1, r2 = r2, r1
        key = (r1, r2, c1, c2)
        res = range_cache.get(key)
        if res is None:
            res = tuple(
                f"{chr(c)}{r}"
                for r in range(r1, r2 + 1)
                for c in range(c1, c2 + 1)
                if f"{chr(c)}{r}" in cells
            )
            range_cache[key] = res
        return res

    def compile_formula(src: str) -> list[tuple]:
        tokens: list[tuple[int, int | str]] = []
        for m in _TOKEN_RE.finditer(src):
            g1, g2, g3, g4 = m.groups()
            if g1 is not None:
                tokens.append((0, int(g1)))
            elif g2 is not None:
                tokens.append((1, g2))
            elif g3 is not None:
                tokens.append((2, g3))
            else:
                tokens.append((3, g4))

        code: list[tuple] = []
        ops: list[str] = []
        ctx_stack: list[list] = []
        state = 1  # 0: START_AGG_ARG, 1: EXPECT_OPERAND, 2: EXPECT_AFTER_ATOM
        pos = 0
        n = len(tokens)

        while True:
            if state == 0:
                if tokens[pos][0] == 1 and pos + 1 < n and tokens[pos + 1] == (3, ":"):
                    c1_name = tokens[pos][1]
                    c2_name = tokens[pos + 2][1]
                    pos += 3
                    present = get_range_cells(c1_name, c2_name)  # type: ignore[arg-type]
                    if present:
                        code.append(("RANGE", present))
                        ctx_stack[-1][4] += len(present)
                    state = 2
                else:
                    ctx_stack[-1][4] += 1
                    state = 1
            elif state == 1:
                neg = False
                while tokens[pos] == (3, "-"):
                    neg = not neg
                    pos += 1
                ttype, tval = tokens[pos]
                pos += 1
                if ttype == 0:
                    v = tval  # type: ignore[assignment]
                    code.append(("CONST", -v if neg else v))
                    state = 2
                elif ttype == 1:
                    code.append(("CELL", tval))
                    if neg:
                        code.append(("NEG",))
                    state = 2
                elif ttype == 3:  # "("
                    ctx_stack.append(["PAREN", neg, ops])
                    ops = []
                    state = 1
                else:  # FUNC
                    pos += 1  # consume "("
                    if tval == "IF":
                        ctx_stack.append(["IF_LEFT", neg, ops])
                        ops = []
                        state = 1
                    else:
                        ctx_stack.append(["AGG", neg, ops, tval, 0])
                        ops = []
                        state = 0
            else:
                if pos == n:
                    while ops:
                        code.append(_OP_INS[ops.pop()])
                    break
                _, tval = tokens[pos]
                pos += 1
                if tval in ("*", "/"):
                    while ops and ops[-1] in ("*", "/"):
                        code.append(_OP_INS[ops.pop()])
                    ops.append(tval)  # type: ignore[arg-type]
                    state = 1
                elif tval in ("+", "-"):
                    while ops:
                        code.append(_OP_INS[ops.pop()])
                    ops.append(tval)  # type: ignore[arg-type]
                    state = 1
                elif tval in _CMP_OPS:
                    while ops:
                        code.append(_OP_INS[ops.pop()])
                    ctx = ctx_stack[-1]
                    ctx[0] = "IF_RIGHT"
                    ctx.append(tval)
                    state = 1
                elif tval == ",":
                    while ops:
                        code.append(_OP_INS[ops.pop()])
                    ctx = ctx_stack[-1]
                    kind = ctx[0]
                    if kind == "AGG":
                        state = 0
                    elif kind == "IF_RIGHT":
                        jfalse_idx = len(code)
                        code.append(())
                        ctx[0] = "IF_THEN"
                        ctx.append(jfalse_idx)
                        state = 1
                    else:  # IF_THEN
                        jmp_idx = len(code)
                        code.append(())
                        code[ctx[4]] = ("JFALSE", ctx[3], len(code))
                        ctx[0] = "IF_ELSE"
                        ctx[3] = jmp_idx
                        state = 1
                else:  # ")"
                    while ops:
                        code.append(_OP_INS[ops.pop()])
                    ctx = ctx_stack.pop()
                    kind, neg, ops = ctx[0], ctx[1], ctx[2]
                    if kind == "AGG":
                        code.append(("AGG", ctx[3], ctx[4]))
                    elif kind == "IF_ELSE":
                        code[ctx[3]] = ("JMP", len(code))
                    if neg:
                        code.append(("NEG",))
                    state = 2

        return code

    call_stack: list[list] = []
    in_progress: set[str] = set()

    def unwind(err: str) -> None:
        for fr in call_stack:
            memo[fr[0]] = err
        call_stack.clear()
        in_progress.clear()

    for start_name in cells:
        if start_name in memo:
            continue
        in_progress.add(start_name)
        call_stack.append([start_name, compile_formula(formulas[start_name]), 0, [], 0])

        while call_stack:
            frame = call_stack[-1]
            code = frame[1]
            pc = frame[2]
            st = frame[3]

            if pc == len(code):
                res = st[0]
                cname = frame[0]
                call_stack.pop()
                in_progress.remove(cname)
                memo[cname] = res
                if call_stack:
                    call_stack[-1][3].append(res)
                continue

            ins = code[pc]
            op = ins[0]

            if op == "CONST":
                st.append(ins[1])
                frame[2] = pc + 1
            elif op == "CELL":
                ref = ins[1]
                if ref not in cells:
                    st.append(0)
                    frame[2] = pc + 1
                elif ref in memo:
                    v = memo[ref]
                    if isinstance(v, str):
                        unwind(v)
                    else:
                        st.append(v)
                        frame[2] = pc + 1
                elif ref in in_progress:
                    unwind("#CYCLE!")
                else:
                    frame[2] = pc + 1
                    in_progress.add(ref)
                    call_stack.append([ref, compile_formula(formulas[ref]), 0, [], 0])
            elif op == "RANGE":
                present = ins[1]
                i = frame[4]
                m_len = len(present)
                while i < m_len:
                    ref = present[i]
                    if ref in memo:
                        v = memo[ref]
                        if isinstance(v, str):
                            unwind(v)
                            break
                        st.append(v)
                        i += 1
                    elif ref in in_progress:
                        unwind("#CYCLE!")
                        break
                    else:
                        frame[4] = i + 1
                        in_progress.add(ref)
                        call_stack.append([ref, compile_formula(formulas[ref]), 0, [], 0])
                        break
                else:
                    frame[4] = 0
                    frame[2] = pc + 1
            elif op == "NEG":
                st[-1] = -st[-1]
                frame[2] = pc + 1
            elif op == "ADD":
                b = st.pop()
                st[-1] += b
                frame[2] = pc + 1
            elif op == "SUB":
                b = st.pop()
                st[-1] -= b
                frame[2] = pc + 1
            elif op == "MUL":
                b = st.pop()
                st[-1] *= b
                frame[2] = pc + 1
            elif op == "DIV":
                b = st.pop()
                a = st.pop()
                if b == 0:
                    unwind("#DIV/0!")
                else:
                    q = abs(a) // abs(b)
                    st.append(-q if (a < 0) ^ (b < 0) else q)
                    frame[2] = pc + 1
            elif op == "JFALSE":
                r = st.pop()
                l = st.pop()
                cmp_op = ins[1]
                if cmp_op == "=":
                    cond = l == r
                elif cmp_op == "<>":
                    cond = l != r
                elif cmp_op == "<":
                    cond = l < r
                elif cmp_op == "<=":
                    cond = l <= r
                elif cmp_op == ">":
                    cond = l > r
                else:
                    cond = l >= r
                frame[2] = pc + 1 if cond else ins[2]
            elif op == "JMP":
                frame[2] = ins[1]
            elif op == "AGG":
                fname = ins[1]
                count = ins[2]
                if count == 0:
                    st.append(0)
                else:
                    vals = st[-count:]
                    del st[-count:]
                    if fname == "SUM":
                        st.append(sum(vals))
                    elif fname == "MIN":
                        st.append(min(vals))
                    else:
                        st.append(max(vals))
                frame[2] = pc + 1

    return {name: memo[name] for name in cells}
